class Person {
    public string Name { get; set; } = "";
    public int Age { get; set; }
}
var person = new Person { Name = "Ира", Age = 20 };
Console.WriteLine(person.Name);

class Animal { public virtual string Sound() => "..."; }
class Dog : Animal { public override string Sound() => "Гав"; }
Animal pet = new Dog();
Console.WriteLine(pet.Sound());

interface IPrintable { void Print(); }
class Report : IPrintable { public void Print() => Console.WriteLine("Отчёт"); }
new Report().Print();

var numbers = new List<int> { 1, 2, 3, 4, 5 };
var even = numbers.Where(n => n % 2 == 0);
Console.WriteLine(string.Join(", ", even));

var names = new[] { "Ира", "Анна", "Борис" };
var sorted = names.OrderBy(n => n);
Console.WriteLine(string.Join(", ", sorted));

